body { font-family: Arial, sans-serif; background-color: #f0f0f0; }
header { background-color: #333; color: #fff; padding: 1em; text-align: center; }
main { max-width: 800px; margin: 2em auto; }
.chat-container { background-color: #fff; padding: 1em; border: 1px solid #ddd; box-shadow: 0 0 10px rgba(0,0,0,0.1); }
.chat-header { background-color: #f7f7f7; padding: 0.5em; border-bottom: 1px solid #ddd; }
.chat-body { padding: 1em; }
.chat-footer { background-color: #f7f7f7; padding: 0.5em; border-top: 1px solid #ddd; }
#user-input { width: 80%; height: 2em; padding: 0.5em; font-size: 1em; }
button { width: 20%; height: 2em; padding: 0.5em; font-size: 1em; background-color: #4CAF50; color: #fff; border: none; border-radius: 0.2em; cursor: pointer; }
button:hover { background-color: #3e8e41; }
.chat-bot { color: #666; margin-bottom: 1em; }

function sendMessage() {
    const userInput = document.getElementById('user-input').value;
    if (userInput.trim()!== '') {
        const chatBody = document.getElementById('chat-body');
        const userMessage = document.createElement('p');
        userMessage.classList.add('user-message');
        userMessage.textContent = userInput;
        chatBody.appendChild(userMessage);
        // TO DO: Implement AI response logic here
        const aiResponse = document.createElement('p');
        aiResponse.classList.add('chat-bot');
        aiResponse.textContent = 'AI: This is a placeholder response. Please integrate the AI model to generate dynamic responses.';
        chatBody.appendChild(aiResponse);
        document.getElementById('user-input').value = '';
    }
}
